let squadPlanSlot='a',squadPlanPreview=null,squadPlanNotice='';
function renderSquadPlans(){
 if(view!=='squad'||squadTab!=='health')return;const host=$('squad-plans-panel');if(!host)return;const model=SquadPlans.read(season),slot=model.slots.find(p=>p.id===squadPlanSlot)||model.slots[0],plan=slot.plan,esc=escapeText;
 if(squadPlanPreview){try{if(SquadPlans.preview(season,squadPlanSlot).fingerprint!==squadPlanPreview.fingerprint){squadPlanPreview=null;squadPlanNotice='선수 상태가 바뀌었습니다. 다시 미리 확인하세요.';}}catch{squadPlanPreview=null;}}
 const preview=squadPlanPreview;
 host.innerHTML=`<section class="squad-plans-card" aria-labelledby="squad-plans-title"><div class="squad-plans-heading"><div><span class="eyebrow">YOUR MATCH PLANS</span><h2 id="squad-plans-title">저장한 선발 계획</h2></div><span>최대 3개 · 구단 저장에 포함</span></div><p>주전·컵 로테이션 등 선발 11명과 포메이션·경기 지시를 기억합니다. 적용 전 선수 상태를 다시 확인하세요.</p><div class="squad-plan-slots" role="group" aria-label="선발 계획 선택">${model.slots.map(x=>`<button type="button" data-squad-plan-slot="${x.id}" aria-pressed="${x.id===slot.id}"><b>${x.id.toUpperCase()}</b><span>${x.plan?esc(x.plan.name):'빈 계획'}</span></button>`).join('')}</div><label class="squad-plan-name">계획 이름<input id="squad-plan-name" type="text" maxlength="24" value="${esc(plan?.name||'계획 '+slot.id.toUpperCase())}"${model.canEdit?'':' disabled'}></label>${plan?`<p class="squad-plan-summary">${esc(plan.name)} · ${plan.formation.split('').join('-')} · ${esc(labels[plan.tactic])}</p>`:'<p class="squad-plan-summary">아직 저장하지 않았습니다. 경기장에서 선발을 정한 뒤 저장하세요.</p>'}<div class="squad-plan-actions"><button type="button" id="save-squad-plan" class="secondary"${model.canEdit?'':' disabled'}>${plan?'현재 선발로 덮어쓰기':'현재 선발 저장'}</button><button type="button" id="preview-squad-plan" class="primary"${plan&&model.canEdit?'':' disabled'}>불러오기 미리보기</button>${plan?'<button type="button" id="delete-squad-plan" class="text-button">이 계획 삭제</button>':''}</div>${!model.canEdit?'<p class="squad-plan-note">새 경기 준비에서 팀 대화 전에 저장·적용할 수 있습니다.</p>':''}${preview?`<section class="squad-plan-preview" aria-label="선발 계획 적용 전 확인"><h3>${esc(preview.name)} · 적용 전 확인</h3><p>${preview.formation.split('').join('-')} · ${esc(labels[preview.tactic])} · 선발 진입 ${preview.entering.length}명 / 제외 ${preview.leaving.length}명</p>${preview.unavailable.length?'<ul class="squad-plan-warnings">'+preview.unavailable.map(p=>`<li>${esc(p.name)} · ${esc(p.reason)}</li>`).join('')+'</ul><p class="squad-plan-note">빈자리는 같은 포지션의 출전 가능한 선수 중 체력, 주요 능력 순으로 채웠습니다.</p>':''}<ul class="squad-plan-eleven">${preview.players.map(p=>`<li><span>${p.pos}</span><strong>${esc(p.name)}</strong><small>체력 ${p.energy}${p.fallback?' · 대체 선발':''}</small></li>`).join('')}</ul>${preview.tired.length?'<p class="squad-plan-note">피로 주의 · '+preview.tired.map(p=>esc(p.name)).join(' · ')+'</p>':''}<div class="squad-plan-actions"><button type="button" id="apply-squad-plan" class="primary">이 선발·전술 적용</button><button type="button" id="cancel-squad-plan" class="secondary">미리보기 취소</button></div></section>`:''}<p id="squad-plan-status" role="status">${esc(squadPlanNotice)}</p><p class="squad-plan-note">부상·출전 정지·이적 선수를 확인해 대체 선발을 제안합니다. 피치의 수동 위치와 개인 역할 표시는 이 계획에 포함하지 않습니다.</p></section>`;
 host.querySelectorAll('[data-squad-plan-slot]').forEach(button=>button.onclick=()=>{squadPlanSlot=button.dataset.squadPlanSlot;squadPlanPreview=null;squadPlanNotice='';renderSquadPlans();host.querySelector('[data-squad-plan-slot="'+squadPlanSlot+'"]')?.focus({preventScroll:true});});
 const act=fn=>{try{fn();$('notice').hidden=true;save();render();}catch(error){squadPlanPreview=null;squadPlanNotice=error.message;renderSquadPlans();}};
 $('save-squad-plan').onclick=()=>act(()=>{season=SquadPlans.save(season,squadPlanSlot,$('squad-plan-name').value);state=season.match;squadPlanPreview=null;squadPlanNotice='현재 선발과 전술을 저장했습니다.';});
 $('preview-squad-plan').onclick=()=>{try{squadPlanPreview=SquadPlans.preview(season,squadPlanSlot);squadPlanNotice='아직 선발을 바꾸지 않았습니다. 아래 11명을 확인하세요.';}catch(error){squadPlanPreview=null;squadPlanNotice=error.message;}renderSquadPlans();};
 const remove=$('delete-squad-plan');if(remove)remove.onclick=()=>act(()=>{season=SquadPlans.remove(season,squadPlanSlot);state=season.match;squadPlanPreview=null;squadPlanNotice='저장한 계획을 삭제했습니다. 현재 선발은 유지됩니다.';});
 const apply=$('apply-squad-plan');if(apply)apply.onclick=()=>{if(apply.disabled)return;apply.disabled=true;act(()=>{if(!squadPlanPreview)throw Error('계획을 다시 미리 확인하세요.');season=SquadPlans.apply(season,squadPlanSlot,squadPlanPreview.fingerprint);state=season.match;selected=null;rotationPreview=null;squadPlanPreview=null;squadPlanNotice='선발과 경기 지시를 적용했습니다.';});};
 const cancel=$('cancel-squad-plan');if(cancel)cancel.onclick=()=>{squadPlanPreview=null;squadPlanNotice='미리보기를 취소했습니다. 현재 선발은 유지됩니다.';renderSquadPlans();};
}
